import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"扫描仪校准周期","description":"","frontmatter":{"title":"扫描仪校准周期","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/scanner-calibration-cycle.md","filePath":"litho/scanner-calibration-cycle.md","lastUpdated":1789023840000}'),p={name:"litho/scanner-calibration-cycle.md"};function _(E,a,m,u,f,b){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="扫描仪校准周期" tabindex="-1">扫描仪校准周期 <a class="header-anchor" href="#扫描仪校准周期" aria-label="Permalink to &quot;扫描仪校准周期&quot;">​</a></h1><div class="epigraph"><p>校准把剂量、焦点、网格和照明瞳拉回机台自己的零。周期太疏，指纹爬出预算；太密，稼动被校准吃掉。</p><footer>—— 对照 scanner calibration / baseline；[机台匹配](/litho/tool-matching)</footer></div><p><a href="/litho/tool-recipe-software">上一课</a>保证执行的是那张配方。缺口是硬件零点会漂：灯、镜头、尺、空气。本课钉校准周期，曝光机单元收到这里；EUV 源从下一课程另起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>激光老化改剂量；热改网格；污染改瞳。在线传感器能追一部分，不能替代离线基准。只做匹配不做单机校准，两台会一起慢慢歪。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层：班次快速检查（剂量、焦点）、日/周网格与照明、月度像差或换件后全套。触发：超 SPC、换激光、动镜头后强制。时间进稼动的计划停，不要和故障混报。与轨道热板校准分开记账。</p>',7)),(e(),s(h,null,{default:r(()=>[d(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20DRIFT%5B%22%E7%81%AF%20%2F%20%E7%83%AD%20%2F%20%E6%B1%A1%E6%9F%93%22%5D%20--%3E%20CAL%5B%22%E6%A0%A1%E5%87%86%22%5D%0A%20%20CAL%20--%3E%20ZERO%5B%22%E5%8D%95%E6%9C%BA%E9%9B%B6%E7%82%B9%22%5D%0A%20%20ZERO%20--%3E%20MATCH%5B%22%E5%86%8D%E8%B0%88%E5%8C%B9%E9%85%8D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>校准片或机内传感器给出偏差，写入校正表。若校准片本身有指纹，会把片指纹写进所有产品。标准片要计量溯源。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 EUV 源校准和掩模厂。下一课程从 EUV 进阶起，源与真空是另一套零点。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>校准维护单机零点；匹配维护机差。</li><li>周期是预算与稼动的折中，要按漂移源分层。</li><li>出处：剂量焦点课；SEMI 校准通识。</li></ul>',6))])}const B=i(p,[["render",_]]);export{T as __pageData,B as default};
